#include <stdio.h>
#include <string.h>
#include <ctype.h>

char s[100][30], op[100][30];
char q[100][4][30], t[100][4][30];
int top = -1, n = 0;

int prec(char c) {
    if (c == '*' || c == '/') return 2;
        if (c == '+' || c == '-') return 1;
            return 0;
            }

            void generate(char *a, char *b, char *c) {
                char temp[30], ref[30];
                    sprintf(temp, "t%d", n + 1);
                        sprintf(ref, "(%d)", n);

                            strcpy(q[n][0], c);
                                strcpy(q[n][1], a);
                                    strcpy(q[n][2], b);
                                        strcpy(q[n][3], temp);

                                            strcpy(t[n][0], c);
                                                strcpy(t[n][1], a);
                                                    strcpy(t[n][2], b);
                                                        strcpy(t[n][3], ref);

                                                            strcpy(s[++top], temp);
                                                                n++;
                                                                }

                                                                int main() {
                                                                    char in[200], token[30];
                                                                        int i = 0, j, k = 0;

                                                                            printf("Enter expression: ");
                                                                                fgets(in, sizeof(in), stdin);

                                                                                    while (in[i]) {
                                                                                            if (isspace(in[i])) { i++; continue; }

                                                                                                    if (isalnum(in[i]) || in[i] == '_') {
                                                                                                                j = 0;
                                                                                                                            while (isalnum(in[i]) || in[i] == '_')
                                                                                                                                            token[j++] = in[i++];
                                                                                                                                                        token[j] = '\0';
                                                                                                                                                                    strcpy(s[++top], token);
                                                                                                                                                                            }
                                                                                                                                                                                    else if (in[i] == '(') {
                                                                                                                                                                                                op[++k][0] = in[i++];
                                                                                                                                                                                                            op[k][1] = '\0';
                                                                                                                                                                                                                    }
                                                                                                                                                                                                                            else if (in[i] == ')') {
                                                                                                                                                                                                                                        while (k && op[k][0] != '(') {
                                                                                                                                                                                                                                                        char c[30], b[30], a[30];
                                                                                                                                                                                                                                                                        strcpy(c, op[k--]);
                                                                                                                                                                                                                                                                                        strcpy(b, s[top--]);
                                                                                                                                                                                                                                                                                                        strcpy(a, s[top--]);
                                                                                                                                                                                                                                                                                                                        generate(a, b, c);
                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                k--; i++;
                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                else {
                                                                                                                                                                                                                                                                                                                                                                            char c = in[i++];
                                                                                                                                                                                                                                                                                                                                                                                        while (k && op[k][0] != '(' &&
                                                                                                                                                                                                                                                                                                                                                                                                           prec(op[k][0]) >= prec(c)) {
                                                                                                                                                                                                                                                                                                                                                                                                                           char x[30], b[30], a[30];
                                                                                                                                                                                                                                                                                                                                                                                                                                           strcpy(x, op[k--]);
                                                                                                                                                                                                                                                                                                                                                                                                                                                           strcpy(b, s[top--]);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                           strcpy(a, s[top--]);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           generate(a, b, x);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   op[++k][0] = c;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               op[k][1] = '\0';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               while (k) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       char c[30], b[30], a[30];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               strcpy(c, op[k--]);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       strcpy(b, s[top--]);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               strcpy(a, s[top--]);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       generate(a, b, c);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               printf("\nQUADRUPLES\n");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   printf("Op\tArg1\tArg2\tResult\n");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       for (i = 0; i < n; i++)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               printf("%s\t%s\t%s\t%s\n",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              q[i][0], q[i][1], q[i][2], q[i][3]);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  printf("\nTRIPLES\n");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      printf("No\tOp\tArg1\tArg2\n");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          for (i = 0; i < n; i++)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  printf("%d\t%s\t%s\t%s\n",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 i, t[i][0], t[i][1], t[i][2]);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     printf("\nINDIRECT TRIPLES\n");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         printf("Pointer\tTriple No\n");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             for (i = 0; i < n; i++)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     printf("%d\t%d\n", i, i);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         return 0;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         }
